# Curated starter entries for the Medical Progress Archive (2016-2026).
# Each DOI is looked up on Crossref by build.py, which supplies the date, journal and official title.
# Text below is written in our own words. Fields: doi, cat, sig (1 landmark, 2 notable), spec, headline, summary, why.
# kw = a word that must appear in the Crossref title (guards against a wrong DOI).
D = []
def add(doi, cat, sig, spec, headline, summary, why, kw, region="global"):
    D.append(dict(doi=doi, cat=cat, sig=sig, spec=spec, headline=headline, summary=summary, why=why, kw=kw.lower(), region=region))

IM, CARD, ENDO, NEPH, ID, NEURO, PULM, GI = "Internal Medicine", "Cardiology", "Endocrinology", "Nephrology", "Infectious Diseases", "Neurology", "Pulmonology", "Gastroenterology"
EM, PSY, HAEM = "Emergency Medicine", "Psychiatry", "Internal Medicine"

# 2016
add("10.1001/jama.2016.0287","definition_classification",1,[EM,IM],"Sepsis-3: new definitions of sepsis and septic shock","Sepsis is redefined as life-threatening organ dysfunction caused by a dysregulated response to infection, identified by a rise of 2 or more SOFA points; qSOFA is proposed as a bedside prompt.","Replaced SIRS-based definitions used in emergency departments and wards worldwide.","sepsis")
add("10.1056/NEJMoa1603827","key_trial",1,[ENDO,CARD],"LEADER: liraglutide lowers cardiovascular events in type 2 diabetes","In 9,340 adults with type 2 diabetes at high cardiovascular risk, liraglutide reduced major cardiovascular events and cardiovascular death compared with placebo.","First GLP-1 receptor agonist shown to reduce cardiovascular death; began the shift to outcome-driven diabetes drug choice.","liraglutide")
add("10.1093/eurheartj/ehw272","guideline_update",2,[CARD,ENDO],"2016 ESC/EAS guidelines for the management of dyslipidaemias","European guidance on lipid testing, risk-based LDL cholesterol targets and treatment.","Reference for lipid targets in Europe and the Middle East until the 2019 update.","dyslipid")
add("10.1056/NEJMoa1513257","key_trial",2,[IM],"Venetoclax in relapsed chronic lymphocytic leukaemia","Targeting BCL2 with venetoclax produced responses in about 79% of 116 patients with relapsed or refractory CLL.","Led to the first approval of a BCL2 inhibitor (FDA, April 2016).","venetoclax")
# 2017
add("10.1056/NEJMoa1615664","key_trial",1,[CARD],"FOURIER: evolocumab added to a statin lowers cardiovascular events","In 27,564 patients with atherosclerotic disease on statins, adding evolocumab lowered LDL cholesterol and reduced major cardiovascular events (about 15% relative reduction in the primary endpoint).","Showed that lowering LDL cholesterol far below earlier targets is beneficial; supports PCSK9-inhibitor use in very-high-risk patients.","evolocumab")
add("10.1056/NEJMoa1707914","key_trial",1,[CARD],"CANTOS: targeting inflammation with canakinumab lowers cardiovascular events","In 10,061 patients after myocardial infarction with raised hs-CRP, canakinumab 150 mg reduced recurrent cardiovascular events without lowering cholesterol.","First proof that lowering inflammation, independent of lipids, reduces atherosclerotic events; not adopted widely because of infection risk and cost.","canakinumab")
add("10.1056/NEJMoa1709118","key_trial",2,[CARD],"COMPASS: low-dose rivaroxaban plus aspirin in stable vascular disease","In 27,395 patients with stable coronary or peripheral artery disease, rivaroxaban 2.5 mg twice daily plus aspirin reduced cardiovascular events versus aspirin alone, with more major bleeding.","Opened the option of dual-pathway inhibition for selected high-risk outpatients.","rivaroxaban")
add("10.1056/NEJMoa1611925","key_trial",2,[ENDO,CARD],"CANVAS: canagliflozin and cardiovascular events in type 2 diabetes","An integrated analysis of two trials in 10,142 participants found fewer major cardiovascular events with canagliflozin and an increased risk of amputation.","Part of the evidence that moved SGLT2 inhibitors from glucose-lowering drugs to cardiovascular and kidney protection.","canagliflozin")
add("10.1161/HYP.0000000000000065","guideline_update",1,[CARD,IM],"2017 ACC/AHA high blood pressure guideline","Defines hypertension as 130/80 mmHg or higher and recommends earlier treatment with out-of-office confirmation.","Changed the US threshold and prompted worldwide debate; European guidelines kept 140/90 for diagnosis.","blood pressure")
add("10.1056/NEJMoa1707447","key_trial",1,[IM],"ZUMA-1: axicabtagene ciloleucel (CAR-T) in refractory large B-cell lymphoma","In 101 patients with refractory large B-cell lymphoma, one CAR-T infusion produced an objective response in 82% and a complete response in 54%.","Basis of the first CAR-T approvals for lymphoma (FDA, October 2017); needs specialist centres to manage cytokine release and neurotoxicity.","axicabtagene")
add("10.1016/S0140-6736(17)31868-8","key_trial",1,[IM],"Voretigene neparvovec (Luxturna): gene therapy for RPE65 retinal dystrophy","A phase 3 trial of a one-time subretinal gene therapy showed improved functional vision in patients with biallelic RPE65 mutations.","First gene therapy approved for an inherited disease in the US (December 2017).","voretigene")
add("10.1056/NEJMoa1606468","key_trial",2,[NEURO],"ORATORIO: ocrelizumab in primary progressive multiple sclerosis","Ocrelizumab slowed confirmed disability progression versus placebo in primary progressive multiple sclerosis.","First therapy to show benefit in primary progressive MS (FDA, March 2017).","ocrelizumab")
add("10.1056/NEJMoa1702752","key_trial",1,[NEURO],"Nusinersen in infantile-onset spinal muscular atrophy","A motor-milestone response occurred in 51% of treated infants versus 0% with sham procedure.","First treatment for spinal muscular atrophy (FDA, December 2016); changed the outlook of a fatal infant disease.","nusinersen")
add("10.1056/NEJMoa1706198","key_trial",1,[NEURO],"Single-dose gene-replacement therapy for spinal muscular atrophy","All 15 infants who received onasemnogene abeparvovec were alive and event-free at 20 months, compared with about 8% in historical controls.","Basis for Zolgensma, approved in 2019 as a one-time gene therapy.","spinal muscular")
add("10.1056/NEJMoa1703068","key_trial",2,[IM],"HAVEN 1: emicizumab prophylaxis in haemophilia A with inhibitors","Weekly emicizumab lowered the bleeding rate by 87% compared with no prophylaxis.","Subcutaneous prophylaxis for haemophilia A, including patients with inhibitors (FDA, November 2017).","emicizumab")
# 2018
add("10.1093/eurheartj/ehy462","definition_classification",1,[CARD,EM],"Fourth Universal Definition of Myocardial Infarction","Distinguishes myocardial infarction from non-ischaemic myocardial injury using a rise and fall of high-sensitivity troponin with clinical evidence of ischaemia, and classifies five types.","The standard definition behind emergency chest-pain pathways and diagnostic coding.","myocardial infarction")
add("10.1056/NEJMoa1805819","key_trial",1,[IM,CARD],"ASPREE: low-dose aspirin in healthy older adults","In 19,114 older adults without cardiovascular disease, aspirin did not prolong disability-free survival and increased major bleeding.","With ASCEND and ARRIVE, ended routine aspirin for primary prevention in older adults.","aspirin")
add("10.1056/NEJMoa1804988","key_trial",2,[ENDO,CARD],"ASCEND: aspirin for primary prevention in diabetes","In 15,480 adults with diabetes and no cardiovascular disease, aspirin reduced serious vascular events but increased major bleeding by a similar amount.","Showed that in diabetes the bleeding cost of aspirin offsets its vascular benefit in primary prevention.","aspirin")
add("10.1016/S0140-6736(18)31924-X","key_trial",2,[CARD,IM],"ARRIVE: aspirin for primary prevention at moderate cardiovascular risk","In 12,546 patients at moderate risk, aspirin did not reduce the composite of cardiovascular events compared with placebo.","Third large trial in 2018 to find little net benefit from aspirin for primary prevention.","aspirin")
add("10.1093/eurheartj/ehy339","guideline_update",2,[CARD,IM],"2018 ESC/ESH guidelines for the management of arterial hypertension","European hypertension guidance: diagnosis at 140/90, treatment targets and a single-pill combination approach.","Reference for hypertension management outside the US until the 2024 update.","hypertension")
add("10.1161/CIR.0000000000000625","guideline_update",1,[CARD,ENDO],"2018 AHA/ACC cholesterol guideline","Introduced risk-enhancing factors and threshold-based use of non-statin drugs; set an LDL-C threshold of 70 mg/dL for adding non-statin therapy in very-high-risk patients.","Shaped statin and add-on therapy decisions worldwide.","cholesterol")
add("10.1056/NEJMoa1709866","key_trial",1,[IM],"Tisagenlecleucel (CAR-T) in children and young adults with B-cell leukaemia","The overall remission rate was 81% within 3 months among 75 patients with relapsed or refractory B-cell acute lymphoblastic leukaemia.","Basis of the first CAR-T approval (FDA, August 2017).","tisagenlecleucel")
add("10.1056/NEJMoa1714448","key_trial",2,[IM],"Larotrectinib in TRK fusion-positive cancers","Across tumour types, 75% of patients with TRK fusion-positive cancers responded to larotrectinib.","An early tumour-agnostic approval: treatment chosen by the genetic change rather than the organ (FDA, November 2018).","larotrectinib")
add("10.1056/NEJMoa1716197","key_trial",2,[ID,EM],"Baloxavir marboxil for uncomplicated influenza","A single dose of baloxavir shortened symptoms versus placebo and reduced viral load faster than oseltamivir.","First new class of influenza antiviral in about two decades (FDA, October 2018).","baloxavir")
add("10.1056/NEJMoa1705848","key_trial",2,[NEURO],"Erenumab for episodic migraine prevention (STRIVE)","Monthly erenumab reduced the number of migraine days per month compared with placebo.","First CGRP-pathway antibody for migraine prevention (FDA, May 2018).","erenumab")
# 2019
add("10.1056/NEJMoa1911303","key_trial",1,[CARD],"DAPA-HF: dapagliflozin in heart failure with reduced ejection fraction","In 4,744 patients with or without diabetes, dapagliflozin lowered worsening heart failure or cardiovascular death by 26%.","Made SGLT2 inhibitors a core heart-failure drug regardless of diabetes.","dapagliflozin")
add("10.1056/NEJMoa1811744","key_trial",1,[NEPH,ENDO],"CREDENCE: canagliflozin protects the kidneys in diabetic kidney disease","In 4,401 patients, canagliflozin reduced kidney failure, doubling of creatinine, or kidney or cardiovascular death by 30%.","First trial to show SGLT2 inhibitors slow kidney disease progression in diabetes.","canagliflozin")
add("10.1056/NEJMoa1901118","key_trial",2,[ENDO],"PIONEER 6: cardiovascular safety of oral semaglutide","In 3,183 patients with type 2 diabetes, oral semaglutide was non-inferior to placebo for major cardiovascular events.","Supported the first oral GLP-1 receptor agonist (Rybelsus, FDA September 2019).","semaglutide")
add("10.1056/NEJMoa1908639","key_trial",1,[PULM],"Elexacaftor-tezacaftor-ivacaftor for cystic fibrosis","In people with one F508del allele, the triple combination improved lung function (FEV1) by about 14 percentage points.","Effective for roughly 90% of people with cystic fibrosis (FDA, October 2019).","elexacaftor")
add("10.1056/NEJMoa1910993","key_trial",1,[ID,EM],"PALM: monoclonal antibodies for Ebola virus disease","Day-28 mortality was 33.5% with REGN-EB3 and 35.1% with mAb114, versus 49.7% with ZMapp and 53.1% with remdesivir.","First treatments proven to lower Ebola mortality.","ebola")
add("10.1161/CIR.0000000000000678","guideline_update",2,[CARD,IM],"2019 ACC/AHA guideline on the primary prevention of cardiovascular disease","Prevention guidance centred on lifestyle, team-based care and shared decision-making; narrowed aspirin use.","Reset US primary-prevention practice, including aspirin.","primary prevention")
add("10.1093/eurheartj/ehz455","guideline_update",1,[CARD,ENDO],"2019 ESC/EAS guidelines for the management of dyslipidaemias","Lower LDL-C goals, including below 55 mg/dL (1.4 mmol/L) for very-high-risk patients.","The most aggressive lipid targets of their time and a model for later guidelines.","dyslipid")
add("10.1093/eurheartj/ehz425","guideline_update",2,[CARD],"2019 ESC guidelines on chronic coronary syndromes","Replaced 'stable coronary artery disease' with chronic coronary syndromes and organised testing by pre-test probability.","Changed how stable chest pain is investigated and labelled.","coronary syndromes")
add("10.1056/NEJMoa1901814","key_trial",1,[ID,PULM],"Bedaquiline, pretomanid and linezolid (BPaL) for highly drug-resistant tuberculosis","A favourable outcome was seen in 90% of 109 patients with extensively drug-resistant or treatment-intolerant multidrug-resistant tuberculosis.","Basis of a six-month, all-oral regimen; pretomanid was approved by the FDA in August 2019.","tuberculosis")
# 2020
add("10.1056/NEJMoa2021436","key_trial",1,[ID,EM],"RECOVERY: dexamethasone lowers mortality in hospitalised COVID-19","28-day mortality fell among patients on ventilation (29.3% vs 41.4%) and on oxygen (23.3% vs 26.2%); no benefit without oxygen.","The first treatment shown to save lives in COVID-19; standard of care within weeks.","dexamethasone")
add("10.1056/NEJMoa2007764","key_trial",2,[ID],"ACTT-1: remdesivir for COVID-19","Remdesivir shortened time to recovery from 15 to 10 days in hospitalised adults.","First antiviral with a proven benefit in COVID-19.","remdesivir")
add("10.1056/NEJMoa2034577","key_trial",1,[ID],"BNT162b2 mRNA vaccine: efficacy against COVID-19","The Pfizer-BioNTech vaccine showed 95% efficacy against symptomatic COVID-19 in people aged 16 and over.","First mRNA vaccine authorised for use in humans (December 2020).","bnt162b2")
add("10.1056/NEJMoa2024816","key_trial",1,[NEPH,CARD],"DAPA-CKD: dapagliflozin in chronic kidney disease with or without diabetes","In 4,304 patients, dapagliflozin reduced kidney failure, sustained eGFR decline of 50% or more, or death by 39%.","Extended kidney protection from SGLT2 inhibitors to people without diabetes.","dapagliflozin")
add("10.1056/NEJMoa2022190","key_trial",2,[CARD],"EMPEROR-Reduced: empagliflozin in heart failure with reduced ejection fraction","In 3,730 patients, empagliflozin lowered cardiovascular death or heart-failure hospitalisation by 25%.","Confirmed the heart-failure benefit of SGLT2 inhibitors first shown in DAPA-HF.","empagliflozin")
add("10.1056/NEJMoa1915922","key_trial",1,[CARD],"ISCHEMIA: invasive versus conservative strategy in stable coronary disease","Over a median 3.2 years, an initial invasive strategy did not reduce death or myocardial infarction compared with optimal medical therapy in stable coronary disease with moderate or severe ischaemia.","Supports medical therapy first for many patients with stable symptoms.","invasive")
add("10.1093/eurheartj/ehaa612","guideline_update",2,[CARD],"2020 ESC guidelines on atrial fibrillation","Introduced the ABC pathway (anticoagulation, better symptom control, comorbidity management) and a structured approach to stroke prevention.","Standardised the integrated management of atrial fibrillation.","atrial fibrillation")
add("10.1056/NEJMoa2025845","key_trial",2,[NEPH,ENDO],"FIDELIO-DKD: finerenone in diabetic kidney disease","In 5,734 patients, finerenone lowered kidney failure, sustained eGFR decline or kidney death by 18%.","Basis of finerenone (Kerendia), approved by the FDA in July 2021.","finerenone")
# 2021
add("10.1056/NEJMoa2032183","key_trial",1,[ENDO],"STEP 1: semaglutide 2.4 mg weekly for obesity","Mean weight loss was 14.9% versus 2.4% with placebo at 68 weeks in 1,961 adults with overweight or obesity.","Established GLP-1 therapy as a major obesity treatment (Wegovy, FDA June 2021).","semaglutide")
add("10.1056/NEJMoa2035389","key_trial",2,[ID],"mRNA-1273 vaccine: efficacy against COVID-19","The Moderna vaccine showed 94.1% efficacy against symptomatic COVID-19.","Second mRNA vaccine to show high efficacy; widely used in Saudi Arabia and worldwide.","sars-cov-2")
add("10.1056/NEJMoa2107038","key_trial",1,[CARD],"EMPEROR-Preserved: empagliflozin in heart failure with preserved ejection fraction","In 5,988 patients, empagliflozin lowered cardiovascular death or heart-failure hospitalisation by 21%.","First drug class to show benefit in heart failure with preserved ejection fraction.","empagliflozin")
add("10.1056/NEJMoa2103695","key_trial",2,[IM,PULM],"Sotorasib for KRAS G12C-mutated lung cancer","About 37% of patients with previously treated non-small-cell lung cancer responded to sotorasib.","First drug to target KRAS, long considered untreatable (FDA, May 2021).","sotorasib")
add("10.1007/s00134-021-06506-y","guideline_update",1,[EM,IM],"Surviving Sepsis Campaign: international guidelines for sepsis and septic shock 2021","Updated recommendations on screening, antimicrobial timing, fluids, vasopressors and corticosteroids.","Reference standard for sepsis care in emergency and critical care.","sepsis")
add("10.1093/eurheartj/ehab484","guideline_update",1,[CARD,IM],"2021 ESC guidelines on cardiovascular disease prevention","Introduced SCORE2 and SCORE2-OP risk estimation for fatal and non-fatal events.","Replaced SCORE with updated risk prediction across Europe and the Middle East.","prevention")
add("10.1056/NEJMoa2118542","key_trial",1,[ID],"EPIC-HR: nirmatrelvir plus ritonavir for COVID-19 in high-risk adults","Treatment started within 3 days of symptoms cut hospitalisation or death by 89% in non-hospitalised high-risk adults.","Basis of oral Paxlovid, authorised from December 2021.","nirmatrelvir")
add("10.1056/NEJMoa2107519","key_trial",1,[ENDO],"SURPASS-2: tirzepatide versus semaglutide in type 2 diabetes","HbA1c fell by 2.0 to 2.3 percentage points with tirzepatide versus 1.9 with semaglutide 1 mg, with greater weight loss.","Basis of tirzepatide (Mounjaro), the first dual GIP/GLP-1 agonist (FDA, May 2022).","tirzepatide")
# 2022
add("10.1056/NEJMoa2206038","key_trial",1,[ENDO],"SURMOUNT-1: tirzepatide for obesity","Weight fell by 15.0%, 19.5% and 20.9% with 5, 10 and 15 mg versus 3.1% with placebo at 72 weeks.","Set a new benchmark for drug-induced weight loss (Zepbound, FDA November 2023).","tirzepatide")
add("10.1056/NEJMoa2212948","key_trial",1,[NEURO],"CLARITY-AD: lecanemab in early Alzheimer's disease","Lecanemab slowed decline on the CDR-SB scale by 27% over 18 months; amyloid-related imaging abnormalities occurred.","First anti-amyloid antibody with full FDA approval (July 2023); registered in Saudi Arabia in July 2025.","lecanemab")
add("10.1056/NEJMoa2206286","key_trial",1,[CARD],"DELIVER: dapagliflozin in heart failure with mildly reduced or preserved ejection fraction","In 6,263 patients, dapagliflozin lowered worsening heart failure or cardiovascular death by 18%.","Extended SGLT2-inhibitor benefit across the ejection-fraction spectrum.","dapagliflozin")
add("10.1056/NEJMoa2204233","key_trial",1,[NEPH],"EMPA-KIDNEY: empagliflozin in chronic kidney disease","In 6,609 patients, empagliflozin lowered kidney disease progression or cardiovascular death by 28%.","Confirmed SGLT2 inhibitors as standard therapy in many forms of chronic kidney disease.","empagliflozin")
add("10.1161/CIR.0000000000001063","guideline_update",1,[CARD],"2022 AHA/ACC/HFSA guideline for the management of heart failure","Four-drug foundation (ARNI/ACE inhibitor/ARB, beta-blocker, mineralocorticoid antagonist, SGLT2 inhibitor) and a new category for improved ejection fraction.","Defines modern heart-failure drug therapy.","heart failure")
add("10.1056/NEJMoa2207323","key_trial",1,[ID],"Monkeypox virus infection in humans across 16 countries","A series of 528 infections described the clinical features of the 2022 outbreak; 98% were in gay or bisexual men.","Described the global mpox outbreak declared a public-health emergency by the WHO on 23 July 2022.","monkeypox")
add("10.1056/NEJMoa2116133","key_trial",2,[IM],"ZUMA-7: axicabtagene ciloleucel as second-line therapy for large B-cell lymphoma","Event-free survival was superior with CAR-T therapy compared with standard second-line care.","Moved CAR-T from last resort to second-line treatment.","axicabtagene")
add("10.1056/NEJMoa2113206","key_trial",2,[IM],"Betibeglogene autotemcel gene therapy for transfusion-dependent beta-thalassaemia","Most treated patients with non-β0/β0 genotypes became transfusion independent.","Relevant where thalassaemia is common, including the Gulf (FDA, August 2022).","thalassemia")
# 2023
add("10.1056/NEJMoa2307563","key_trial",1,[ENDO,CARD],"SELECT: semaglutide lowers cardiovascular events in obesity without diabetes","In 17,604 adults with established cardiovascular disease and overweight or obesity, weekly semaglutide reduced major cardiovascular events by 20%.","Showed that treating obesity pharmacologically can reduce heart attacks and strokes.","semaglutide")
add("10.1056/NEJMoa2209604","key_trial",1,[ID,PULM],"RSV vaccine in adults 60 years and older","The prefusion F vaccine had 82.6% efficacy against RSV lower respiratory tract disease.","First RSV vaccines for older adults were approved in May 2023 (Arexvy, Abrysvo).","respiratory syncytial")
add("10.1056/NEJMoa2216480","key_trial",2,[ID,"Obstetrics and Gynecology"],"Maternal RSV vaccine to protect infants","Vaccination in pregnancy had 81.8% efficacy against severe RSV lower respiratory illness in infants within 90 days.","Basis of the first maternal RSV vaccine (Abrysvo).","pregnancy")
add("10.1056/NEJMoa2309676","key_trial",1,[IM],"Exagamglogene autotemcel (Casgevy) for sickle cell disease","29 of 30 evaluable patients were free of severe vaso-occlusive crises for at least 12 months.","First CRISPR-based therapy approved (UK November 2023, FDA December 2023; Saudi Arabia January 2024).","sickle")
add("10.1056/NEJMoa2309673","key_trial",1,[IM],"Exagamglogene autotemcel (Casgevy) for transfusion-dependent beta-thalassaemia","39 of 42 patients were transfusion independent for at least 12 months.","A one-time gene-editing option for a disease that is common in the Middle East.","thalassemia")
add("10.1097/HEP.0000000000000520","definition_classification",1,[GI,ENDO],"A new nomenclature for steatotic liver disease: MASLD and MASH","NAFLD and NASH are replaced by metabolic dysfunction-associated steatotic liver disease (MASLD) and steatohepatitis (MASH), with positive cardiometabolic criteria.","Changes the terminology in reports, codes and trials.","nomenclature")
add("10.1161/CIR.0000000000001184","definition_classification",1,[CARD,ENDO,NEPH],"Cardiovascular-kidney-metabolic (CKM) health: AHA presidential advisory","Defines CKM syndrome and staging linking obesity, diabetes, chronic kidney disease and cardiovascular disease.","Frames these conditions as one connected disease process.","cardiovascular-kidney-metabolic")
add("10.1093/eurheartj/ehad191","guideline_update",1,[CARD,EM],"2023 ESC guidelines for the management of acute coronary syndromes","Updated recommendations on diagnosis with high-sensitivity troponin, antithrombotic therapy and early invasive strategy.","Reference for acute coronary syndrome care in emergency departments.","acute coronary")
add("10.1056/NEJMoa2213558","key_trial",1,[PULM,CARD],"STELLAR: sotatercept in pulmonary arterial hypertension","Sotatercept improved six-minute walk distance by about 41 metres versus placebo when added to background therapy.","A new class of drug for pulmonary arterial hypertension (Winrevair, FDA March 2024).","sotatercept")
add("10.1001/jama.2023.13239","key_trial",2,[NEURO],"TRAILBLAZER-ALZ 2: donanemab in early symptomatic Alzheimer's disease","Donanemab slowed clinical decline by 35% on iADRS in patients with low or medium tau.","Basis of donanemab (Kisunla), approved by the FDA in July 2024.","donanemab")
# 2024
add("10.1056/NEJMoa2309000","key_trial",1,[GI],"MAESTRO-NASH: resmetirom in NASH with liver fibrosis","NASH resolution occurred in 26 to 30% versus 10% with placebo; fibrosis improved in 24 to 26% versus 14%.","First drug approved for MASH with fibrosis (Rezdiffra, FDA March 2024).","resmetirom")
add("10.1056/NEJMoa2403347","key_trial",1,[NEPH,ENDO],"FLOW: semaglutide and kidney outcomes in type 2 diabetes","Semaglutide lowered major kidney disease events by 24% in patients with type 2 diabetes and chronic kidney disease.","Added GLP-1 receptor agonists to the kidney-protection toolkit.","semaglutide")
add("10.1016/j.kint.2023.10.018","guideline_update",2,[NEPH],"KDIGO 2024 clinical practice guideline for chronic kidney disease","Updated evaluation and management, including risk-based staging and SGLT2-inhibitor use.","Reference guideline for chronic kidney disease worldwide.","kidney")
add("10.1093/eurheartj/ehae178","guideline_update",1,[CARD,IM],"2024 ESC guidelines for the management of elevated blood pressure and hypertension","Introduced an 'elevated blood pressure' category (120 to 139 / 70 to 89 mmHg) and a systolic target of 120 to 129 mmHg for most treated adults.","Moves European practice toward earlier, lower-target treatment.","blood pressure")
add("10.1093/eurheartj/ehae176","guideline_update",2,[CARD],"2024 ESC guidelines for the management of atrial fibrillation","The AF-CARE pathway: comorbidity management, avoid stroke, better symptom control, evaluation and dynamic reassessment.","Updated the structure of atrial fibrillation care.","atrial fibrillation")
add("10.1056/NEJMoa2407001","key_trial",1,[ID],"PURPOSE 1: twice-yearly lenacapavir for HIV prevention in young women","There were no HIV infections among the 2,134 women who received lenacapavir.","Basis of the first twice-yearly HIV prevention injection.","lenacapavir")
add("10.1056/NEJMoa2404881","key_trial",2,[PULM,ENDO],"SURMOUNT-OSA: tirzepatide in obstructive sleep apnoea with obesity","Tirzepatide reduced the apnoea-hypopnoea index by about 25 to 29 events per hour.","First drug approved for obstructive sleep apnoea (FDA, December 2024).","tirzepatide")
add("10.1164/rccm.202306-0944OC","key_trial",2,[PULM],"ENHANCE-1: ensifentrine in COPD","Ensifentrine improved FEV1 by about 87 mL at 12 weeks.","First new inhaled mechanism for COPD in about 20 years (FDA, June 2024).","ensifentrine")
# 2025
add("10.1161/CIR.0000000000001356","guideline_update",1,[CARD,IM],"2025 AHA/ACC guideline for the prevention, detection, evaluation and management of high blood pressure in adults","Uses the PREVENT equations to guide earlier treatment, with team-based care and attention to out-of-office measurement.","Updates US hypertension practice for the first time since 2017.","blood pressure")
add("10.1016/S2213-8587(24)00316-4","definition_classification",1,[ENDO,IM],"Definition and diagnostic criteria of clinical obesity (Lancet Commission)","Separates clinical obesity (obesity with organ dysfunction or functional limitation) from preclinical obesity.","Changes how obesity is diagnosed and who is prioritised for treatment.","obesity")
add("10.1056/NEJMoa2504747","key_trial",1,[IM],"Patient-specific in vivo gene editing to treat a rare metabolic disease","A personalised base-editing therapy was designed, made and given to an infant with CPS1 deficiency in a few months.","First personalised gene-editing treatment for a single patient.","gene editing")
